/* Shared declarations for the xz reimplementation. */
#ifndef XZR_COMMON_H
#define XZR_COMMON_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>

#define VLI_UNKNOWN UINT64_MAX
#define VLI_MAX (UINT64_MAX / 2)
#define VLI_BYTES_MAX (sizeof(uint64_t) * 8 / 7)

#define FILTERS_MAX 4

/* Filter IDs used by the .xz format. */
#define FILTER_DELTA       UINT64_C(0x03)
#define FILTER_X86         UINT64_C(0x04)
#define FILTER_POWERPC     UINT64_C(0x05)
#define FILTER_IA64        UINT64_C(0x06)
#define FILTER_ARM         UINT64_C(0x07)
#define FILTER_ARMTHUMB    UINT64_C(0x08)
#define FILTER_SPARC       UINT64_C(0x09)
#define FILTER_ARM64       UINT64_C(0x0A)
#define FILTER_RISCV       UINT64_C(0x0B)
#define FILTER_LZMA1       UINT64_C(0x4000000000000001)
#define FILTER_LZMA2       UINT64_C(0x21)

/* Integrity check types. */
enum {
	CHECK_NONE = 0,
	CHECK_CRC32 = 1,
	CHECK_CRC64 = 4,
	CHECK_SHA256 = 10,
	CHECK_ID_MAX = 15
};

#define CHECK_SIZE_MAX 64

/* Return codes shared by the coders. */
typedef enum {
	XZ_OK = 0,
	XZ_STREAM_END = 1,
	XZ_NO_CHECK = 2,
	XZ_UNSUPPORTED_CHECK = 3,
	XZ_GET_CHECK = 4,
	XZ_MEM_ERROR = 5,
	XZ_MEMLIMIT_ERROR = 6,
	XZ_FORMAT_ERROR = 7,
	XZ_OPTIONS_ERROR = 8,
	XZ_DATA_ERROR = 9,
	XZ_BUF_ERROR = 10,
	XZ_PROG_ERROR = 11,
	XZ_SEEK_NEEDED = 12
} xz_ret;

typedef enum {
	ACTION_RUN = 0,
	ACTION_SYNC_FLUSH = 1,
	ACTION_FULL_FLUSH = 2,
	ACTION_FINISH = 3,
	ACTION_FULL_BARRIER = 4
} xz_action;

/* LZMA options. */
typedef struct {
	uint32_t dict_size;
	const uint8_t *preset_dict;
	uint32_t preset_dict_size;
	uint32_t lc, lp, pb;
	uint32_t mode;      /* 1 = fast, 2 = normal */
	uint32_t nice_len;
	uint32_t mf;
	uint32_t depth;
	uint32_t ext_flags;
	uint32_t ext_size_low;
	uint32_t ext_size_high;
} lzma_options;

#define MODE_FAST 1
#define MODE_NORMAL 2

#define MF_HC3 0x03
#define MF_HC4 0x04
#define MF_BT2 0x12
#define MF_BT3 0x13
#define MF_BT4 0x14

#define LC_DEFAULT 3
#define LP_DEFAULT 0
#define PB_DEFAULT 2

#define DICT_SIZE_MIN 4096u
#define DICT_SIZE_MAX (UINT32_C(1) << 30)   /* encoder limit: 1536 MiB check separately */

typedef struct {
	uint32_t dist;
} delta_options;

typedef struct {
	uint32_t start_offset;
} bcj_options;

typedef struct {
	uint64_t id;
	void *options;
} filter_info;

/* CRC / hash */
extern uint32_t xcrc32(const uint8_t *buf, size_t size, uint32_t crc);
extern uint64_t xcrc64(const uint8_t *buf, size_t size, uint64_t crc);

typedef struct {
	uint32_t state[8];
	uint64_t size;
	uint8_t buffer[64];
} sha256_state;

extern void sha256_init(sha256_state *s);
extern void sha256_update(sha256_state *s, const uint8_t *buf, size_t size);
extern void sha256_finish(sha256_state *s, uint8_t *out);

/* Unaligned helpers */
static inline uint16_t read16be(const uint8_t *p)
{
	return (uint16_t)(((uint32_t)p[0] << 8) | p[1]);
}
static inline uint32_t read32be(const uint8_t *p)
{
	return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16)
			| ((uint32_t)p[2] << 8) | p[3];
}
static inline uint32_t read32le(const uint8_t *p)
{
	return (uint32_t)p[0] | ((uint32_t)p[1] << 8)
			| ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
}
static inline uint64_t read64le(const uint8_t *p)
{
	return (uint64_t)read32le(p) | ((uint64_t)read32le(p + 4) << 32);
}
static inline void write32le(uint8_t *p, uint32_t v)
{
	p[0] = (uint8_t)v; p[1] = (uint8_t)(v >> 8);
	p[2] = (uint8_t)(v >> 16); p[3] = (uint8_t)(v >> 24);
}
static inline void write32be(uint8_t *p, uint32_t v)
{
	p[0] = (uint8_t)(v >> 24); p[1] = (uint8_t)(v >> 16);
	p[2] = (uint8_t)(v >> 8); p[3] = (uint8_t)v;
}
static inline void write64le(uint8_t *p, uint64_t v)
{
	write32le(p, (uint32_t)v);
	write32le(p + 4, (uint32_t)(v >> 32));
}

static inline uint64_t my_min64(uint64_t a, uint64_t b) { return a < b ? a : b; }
static inline uint64_t my_max64(uint64_t a, uint64_t b) { return a > b ? a : b; }
static inline uint32_t my_min32(uint32_t a, uint32_t b) { return a < b ? a : b; }
static inline uint32_t my_max32(uint32_t a, uint32_t b) { return a > b ? a : b; }

extern uint32_t check_size(uint32_t id);

/* Variable length integer coding */
extern xz_ret vli_decode(uint64_t *vli, size_t *vli_pos, const uint8_t *in,
		size_t *in_pos, size_t in_size);
extern xz_ret vli_encode(uint64_t vli, size_t *vli_pos, uint8_t *out,
		size_t *out_pos, size_t out_size);
extern uint32_t vli_size(uint64_t vli);

extern bool lzma_preset(lzma_options *opt, uint32_t preset);
extern uint64_t lzma_encoder_memusage(const lzma_options *opt);
extern uint64_t lzma_decoder_memusage(const lzma_options *opt);
extern uint64_t raw_encoder_memusage(const filter_info *filters);
extern uint64_t raw_decoder_memusage(const filter_info *filters);

#endif

