#include "common.h"

static uint32_t crc32_table[8][256];
static uint64_t crc64_table[4][256];
static bool tables_ready = false;

static void init_tables(void)
{
	uint32_t i, j, s;
	for (i = 0; i < 256; ++i) {
		uint32_t c = i;
		for (j = 0; j < 8; ++j)
			c = (c >> 1) ^ (0xEDB88320u & (uint32_t)(-(int32_t)(c & 1)));
		crc32_table[0][i] = c;
	}
	for (s = 1; s < 8; ++s)
		for (i = 0; i < 256; ++i)
			crc32_table[s][i] = (crc32_table[s - 1][i] >> 8)
					^ crc32_table[0][crc32_table[s - 1][i] & 0xFF];

	for (i = 0; i < 256; ++i) {
		uint64_t c = i;
		for (j = 0; j < 8; ++j)
			c = (c >> 1) ^ (UINT64_C(0xC96C5795D7870F42)
					& (uint64_t)(-(int64_t)(c & 1)));
		crc64_table[0][i] = c;
	}
	for (s = 1; s < 4; ++s)
		for (i = 0; i < 256; ++i)
			crc64_table[s][i] = (crc64_table[s - 1][i] >> 8)
					^ crc64_table[0][crc64_table[s - 1][i] & 0xFF];

	tables_ready = true;
}

uint32_t xcrc32(const uint8_t *buf, size_t size, uint32_t crc)
{
	if (!tables_ready)
		init_tables();
	crc = ~crc;
	while (size-- != 0)
		crc = crc32_table[0][(crc ^ *buf++) & 0xFF] ^ (crc >> 8);
	return ~crc;
}

uint64_t xcrc64(const uint8_t *buf, size_t size, uint64_t crc)
{
	if (!tables_ready)
		init_tables();
	crc = ~crc;
	while (size-- != 0)
		crc = crc64_table[0][(crc ^ *buf++) & 0xFF] ^ (crc >> 8);
	return ~crc;
}

/* SHA-256 */
static const uint32_t sha_k[64] = {
	0x428A2F98, 0x71374491, 0xB5C0FBCF, 0xE9B5DBA5,
	0x3956C25B, 0x59F111F1, 0x923F82A4, 0xAB1C5ED5,
	0xD807AA98, 0x12835B01, 0x243185BE, 0x550C7DC3,
	0x72BE5D74, 0x80DEB1FE, 0x9BDC06A7, 0xC19BF174,
	0xE49B69C1, 0xEFBE4786, 0x0FC19DC6, 0x240CA1CC,
	0x2DE92C6F, 0x4A7484AA, 0x5CB0A9DC, 0x76F988DA,
	0x983E5152, 0xA831C66D, 0xB00327C8, 0xBF597FC7,
	0xC6E00BF3, 0xD5A79147, 0x06CA6351, 0x14292967,
	0x27B70A85, 0x2E1B2138, 0x4D2C6DFC, 0x53380D13,
	0x650A7354, 0x766A0ABB, 0x81C2C92E, 0x92722C85,
	0xA2BFE8A1, 0xA81A664B, 0xC24B8B70, 0xC76C51A3,
	0xD192E819, 0xD6990624, 0xF40E3585, 0x106AA070,
	0x19A4C116, 0x1E376C08, 0x2748774C, 0x34B0BCB5,
	0x391C0CB3, 0x4ED8AA4A, 0x5B9CCA4F, 0x682E6FF3,
	0x748F82EE, 0x78A5636F, 0x84C87814, 0x8CC70208,
	0x90BEFFFA, 0xA4506CEB, 0xBEF9A3F7, 0xC67178F2,
};

#define ROR32(x, n) (((x) >> (n)) | ((x) << (32 - (n))))

static void sha256_block(sha256_state *s, const uint8_t *block)
{
	uint32_t w[64];
	uint32_t a, b, c, d, e, f, g, h;
	size_t i;

	for (i = 0; i < 16; ++i)
		w[i] = read32be(block + i * 4);
	for (i = 16; i < 64; ++i) {
		const uint32_t s0 = ROR32(w[i - 15], 7) ^ ROR32(w[i - 15], 18)
				^ (w[i - 15] >> 3);
		const uint32_t s1 = ROR32(w[i - 2], 17) ^ ROR32(w[i - 2], 19)
				^ (w[i - 2] >> 10);
		w[i] = w[i - 16] + s0 + w[i - 7] + s1;
	}

	a = s->state[0]; b = s->state[1]; c = s->state[2]; d = s->state[3];
	e = s->state[4]; f = s->state[5]; g = s->state[6]; h = s->state[7];

	for (i = 0; i < 64; ++i) {
		const uint32_t s1 = ROR32(e, 6) ^ ROR32(e, 11) ^ ROR32(e, 25);
		const uint32_t ch = (e & f) ^ (~e & g);
		const uint32_t t1 = h + s1 + ch + sha_k[i] + w[i];
		const uint32_t s0 = ROR32(a, 2) ^ ROR32(a, 13) ^ ROR32(a, 22);
		const uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
		const uint32_t t2 = s0 + maj;
		h = g; g = f; f = e; e = d + t1;
		d = c; c = b; b = a; a = t1 + t2;
	}

	s->state[0] += a; s->state[1] += b; s->state[2] += c; s->state[3] += d;
	s->state[4] += e; s->state[5] += f; s->state[6] += g; s->state[7] += h;
}

void sha256_init(sha256_state *s)
{
	static const uint32_t iv[8] = {
		0x6A09E667, 0xBB67AE85, 0x3C6EF372, 0xA54FF53A,
		0x510E527F, 0x9B05688C, 0x1F83D9AB, 0x5BE0CD19,
	};
	memcpy(s->state, iv, sizeof(iv));
	s->size = 0;
}

void sha256_update(sha256_state *s, const uint8_t *buf, size_t size)
{
	size_t have = (size_t)(s->size & 63);
	s->size += size;
	if (have != 0) {
		const size_t need = 64 - have;
		if (size < need) {
			memcpy(s->buffer + have, buf, size);
			return;
		}
		memcpy(s->buffer + have, buf, need);
		sha256_block(s, s->buffer);
		buf += need;
		size -= need;
	}
	while (size >= 64) {
		sha256_block(s, buf);
		buf += 64;
		size -= 64;
	}
	if (size != 0)
		memcpy(s->buffer, buf, size);
}

void sha256_finish(sha256_state *s, uint8_t *out)
{
	const uint64_t bits = s->size * 8;
	size_t have = (size_t)(s->size & 63);
	size_t i;

	s->buffer[have++] = 0x80;
	if (have > 56) {
		memset(s->buffer + have, 0, 64 - have);
		sha256_block(s, s->buffer);
		have = 0;
	}
	memset(s->buffer + have, 0, 56 - have);
	write32be(s->buffer + 56, (uint32_t)(bits >> 32));
	write32be(s->buffer + 60, (uint32_t)bits);
	sha256_block(s, s->buffer);

	for (i = 0; i < 8; ++i)
		write32be(out + i * 4, s->state[i]);
}

uint32_t check_size(uint32_t id)
{
	static const uint8_t sizes[16] = {
		0, 4, 4, 4, 8, 8, 8, 16, 16, 16, 32, 32, 32, 64, 64, 64
	};
	return sizes[id & 15];
}

xz_ret vli_decode(uint64_t *vli, size_t *vli_pos, const uint8_t *in,
		size_t *in_pos, size_t in_size)
{
	size_t vli_pos_internal = 0;
	if (vli_pos == NULL) {
		vli_pos = &vli_pos_internal;
		*vli = 0;
	}
	if (*in_pos >= in_size)
		return XZ_BUF_ERROR;
	if (*vli_pos == 0)
		*vli = 0;

	while (true) {
		const uint8_t byte = in[*in_pos];
		++*in_pos;
		*vli += (uint64_t)(byte & 0x7F) << (*vli_pos * 7);
		++*vli_pos;
		if ((byte & 0x80) == 0) {
			if (byte == 0 && *vli_pos > 1)
				return XZ_DATA_ERROR;
			return vli_pos == &vli_pos_internal ? XZ_OK : XZ_STREAM_END;
		}
		if (*vli_pos == VLI_BYTES_MAX)
			return XZ_DATA_ERROR;
		if (*in_pos >= in_size)
			return vli_pos == &vli_pos_internal
					? XZ_DATA_ERROR : XZ_OK;
	}
}

xz_ret vli_encode(uint64_t vli, size_t *vli_pos, uint8_t *out,
		size_t *out_pos, size_t out_size)
{
	size_t vli_pos_internal = 0;
	if (vli_pos == NULL)
		vli_pos = &vli_pos_internal;

	if (vli > VLI_MAX)
		return XZ_PROG_ERROR;

	while (*out_pos < out_size) {
		if (vli < 0x80) {
			out[*out_pos] = (uint8_t)vli;
			++*out_pos;
			++*vli_pos;
			return vli_pos == &vli_pos_internal ? XZ_OK : XZ_STREAM_END;
		}
		out[*out_pos] = (uint8_t)(vli & 0x7F) | 0x80;
		++*out_pos;
		++*vli_pos;
		vli >>= 7;
	}
	return vli_pos == &vli_pos_internal ? XZ_PROG_ERROR : XZ_OK;
}

uint32_t vli_size(uint64_t vli)
{
	uint32_t i = 0;
	do {
		vli >>= 7;
		++i;
	} while (vli != 0);
	return i;
}

