#ifndef XZR_LZMA_COMMON_H
#define XZR_LZMA_COMMON_H

#include "common.h"

typedef uint16_t probability;

#define RC_SHIFT_BITS 8
#define RC_TOP_BITS 24
#define RC_TOP_VALUE (UINT32_C(1) << RC_TOP_BITS)
#define RC_BIT_MODEL_TOTAL_BITS 11
#define RC_BIT_MODEL_TOTAL (UINT32_C(1) << RC_BIT_MODEL_TOTAL_BITS)
#define RC_MOVE_BITS 5

#define POS_STATES_MAX (1 << 4)
#define STATES 12
#define LIT_STATES 7

#define LITERAL_CODER_SIZE 0x300
#define LITERAL_CODERS_MAX (1 << 4)

#define MATCH_LEN_MIN 2
#define MATCH_LEN_MAX (MATCH_LEN_MIN + LEN_LOW_SYMBOLS + LEN_MID_SYMBOLS \
		+ LEN_HIGH_SYMBOLS - 1)
#define LEN_LOW_BITS 3
#define LEN_LOW_SYMBOLS (1 << LEN_LOW_BITS)
#define LEN_MID_BITS 3
#define LEN_MID_SYMBOLS (1 << LEN_MID_BITS)
#define LEN_HIGH_BITS 8
#define LEN_HIGH_SYMBOLS (1 << LEN_HIGH_BITS)

#define DIST_STATES 4
#define DIST_SLOT_BITS 6
#define DIST_SLOTS (1 << DIST_SLOT_BITS)
#define DIST_MODEL_START 4
#define DIST_MODEL_END 14
#define FULL_DISTANCES_BITS (DIST_MODEL_END / 2)
#define FULL_DISTANCES (1 << FULL_DISTANCES_BITS)
#define ALIGN_BITS 4
#define ALIGN_SIZE (1 << ALIGN_BITS)
#define ALIGN_MASK (ALIGN_SIZE - 1)

#define REPS 4

static inline uint32_t get_dist_state(uint32_t len)
{
	return len < DIST_STATES + MATCH_LEN_MIN
			? len - MATCH_LEN_MIN : DIST_STATES - 1;
}

static inline bool is_lit_state(uint32_t state) { return state < LIT_STATES; }

static inline void update_literal(uint32_t *state)
{
	*state = *state <= 3 ? 0 : (*state <= 9 ? *state - 3 : *state - 6);
}
static inline void update_match(uint32_t *state)
{
	*state = *state < LIT_STATES ? 7 : 10;
}
static inline void update_long_rep(uint32_t *state)
{
	*state = *state < LIT_STATES ? 8 : 11;
}
static inline void update_short_rep(uint32_t *state)
{
	*state = *state < LIT_STATES ? 9 : 11;
}

static inline uint32_t literal_subcoder_index(uint32_t lc, uint32_t lp_mask,
		uint32_t pos, uint8_t prev_byte)
{
