#include "lzma_decoder.h"
#include "filter.h"

#define LZMA_IN_REQUIRED 64
#define RC_INIT_BYTES 5

/* ---------------- dictionary ---------------- */

bool dict_alloc(dict_t *dict, size_t size)
{
	dict->buf = malloc(size);
	if (dict->buf == NULL)
		return true;
	dict->size = size;
	dict_reset(dict);
	return false;
}

void dict_free(dict_t *dict)
{
	free(dict->buf);
	dict->buf = NULL;
}

void dict_reset(dict_t *dict)
{
	dict->start = 0;
	dict->pos = 0;
	dict->full = 0;
	dict->limit = 0;
}

static inline bool dict_put(dict_t *dict, uint8_t byte)
{
	if (dict->pos == dict->limit)
		return false;
	dict->buf[dict->pos++] = byte;
	if (dict->pos > dict->full)
		dict->full = dict->pos;
	return true;
}

static inline uint8_t dict_get(const dict_t *dict, uint32_t dist)
{
	const size_t offset = dist < dict->pos
			? dict->pos - dist - 1
			: dict->size - (dist - dict->pos) - 1;
	return dict->buf[offset];
}

/* Returns false if the repeat could not be fully done (output full). */
static bool dict_repeat(dict_t *dict, uint32_t *len, uint32_t dist)
{
	size_t back;
	uint32_t left = my_min32((uint32_t)(dict->limit - dict->pos), *len);
	*len -= left;

	back = dist < dict->pos ? dict->pos - dist - 1
			: dict->size - (dist - dict->pos) - 1;
	while (left-- > 0) {
		dict->buf[dict->pos++] = dict->buf[back++];
		if (back == dict->size)
			back = 0;
	}
	if (dict->pos > dict->full)
		dict->full = dict->pos;
	return *len == 0;
}

/* ---------------- range decoder ---------------- */

typedef struct {
	const uint8_t *buf;
	size_t pos;
	size_t size;
	uint32_t range;
	uint32_t code;
	bool overflow;
} rc_src;

static inline uint8_t rc_next(rc_src *s)
{
	if (s->pos >= s->size) {
		s->overflow = true;
		return 0;
	}
	return s->buf[s->pos++];
}

static inline void rc_normalize(rc_src *s)
{
	if (s->range < RC_TOP_VALUE) {
		s->range <<= RC_SHIFT_BITS;
		s->code = (s->code << RC_SHIFT_BITS) | rc_next(s);
	}
}

static inline uint32_t rc_bit(rc_src *s, probability *prob)
{
	uint32_t bound;
	uint32_t bit;
	rc_normalize(s);
	bound = (s->range >> RC_BIT_MODEL_TOTAL_BITS) * (uint32_t)*prob;
	if (s->code < bound) {
		s->range = bound;
		*prob += (probability)((RC_BIT_MODEL_TOTAL - *prob) >> RC_MOVE_BITS);
		bit = 0;
	} else {
		s->range -= bound;
		s->code -= bound;
		*prob -= (probability)(*prob >> RC_MOVE_BITS);
		bit = 1;
	}
	return bit;
}

static inline uint32_t rc_bittree(rc_src *s, probability *probs, uint32_t limit)
{
	uint32_t symbol = 1;
	do {
		symbol = (symbol << 1) + rc_bit(s, probs + symbol);
	} while (symbol < limit);
	return symbol;
}

static inline uint32_t rc_bittree_rev(rc_src *s, probability *probs,
		uint32_t bits)
{
	uint32_t symbol = 1;
	uint32_t i = 0;
	uint32_t dest = 0;
	for (i = 0; i < bits; ++i) {
		const uint32_t bit = rc_bit(s, probs + symbol);
		symbol = (symbol << 1) + bit;
		dest |= bit << i;
	}
	return dest;
}

static inline uint32_t rc_direct(rc_src *s, uint32_t count)
{
	uint32_t result = 0;
	do {
		uint32_t t;
		rc_normalize(s);
		s->range >>= 1;
		s->code -= s->range;
		t = 0 - (s->code >> 31);
		s->code += s->range & t;
		result = (result << 1) + (t + 1);
	} while (--count > 0);
	return result;
}

static uint32_t len_decode(lzma_length_decoder *ld, rc_src *s, uint32_t pos_state)
{
	if (rc_bit(s, &ld->choice) == 0)
		return rc_bittree(s, ld->low[pos_state], LEN_LOW_SYMBOLS)
				- LEN_LOW_SYMBOLS + MATCH_LEN_MIN;
	if (rc_bit(s, &ld->choice2) == 0)
		return rc_bittree(s, ld->mid[pos_state], LEN_MID_SYMBOLS)
				- LEN_MID_SYMBOLS + MATCH_LEN_MIN + LEN_LOW_SYMBOLS;
	return rc_bittree(s, ld->high, LEN_HIGH_SYMBOLS) - LEN_HIGH_SYMBOLS
			+ MATCH_LEN_MIN + LEN_LOW_SYMBOLS + LEN_MID_SYMBOLS;
}

static void len_reset(lzma_length_decoder *ld)
{
	uint32_t i;
	bit_reset(ld->choice);
	bit_reset(ld->choice2);
	for (i = 0; i < POS_STATES_MAX; ++i) {
		bittree_reset(ld->low[i], LEN_LOW_BITS);
		bittree_reset(ld->mid[i], LEN_MID_BITS);
	}
	bittree_reset(ld->high, LEN_HIGH_BITS);
}

bool lzma_dec_set_props(lzma_options *opt, uint8_t byte)
{
	if (byte > (4 * 5 + 4) * 9 + 8)
		return true;
	opt->pb = byte / (9 * 5);
	byte -= opt->pb * 9 * 5;
	opt->lp = byte / 9;
	opt->lc = byte - opt->lp * 9;
	return opt->lc + opt->lp > 4;
}

void lzma_dec_reset(lzma_dec *c, const lzma_options *opt)
{
	uint32_t i, j;

	c->pos_mask = (1u << opt->pb) - 1;
	c->literal_context_bits = opt->lc;
	c->literal_pos_mask = (1u << opt->lp) - 1;

	c->state = 0;
	c->rep0 = c->rep1 = c->rep2 = c->rep3 = 0;
	c->eopm_seen = false;

	for (i = 0; i < STATES; ++i) {
		for (j = 0; j <= c->pos_mask; ++j) {
			bit_reset(c->is_match[i][j]);
			bit_reset(c->is_rep0_long[i][j]);
		}
		bit_reset(c->is_rep[i]);
		bit_reset(c->is_rep0[i]);
		bit_reset(c->is_rep1[i]);
		bit_reset(c->is_rep2[i]);
	}
	for (i = 0; i < DIST_STATES; ++i)
		bittree_reset(c->dist_slot[i], DIST_SLOT_BITS);
	for (i = 0; i < FULL_DISTANCES - DIST_MODEL_END; ++i)
		bit_reset(c->pos_special[i]);
	bittree_reset(c->pos_align, ALIGN_BITS);
	len_reset(&c->match_len_dec);
	len_reset(&c->rep_len_dec);

	{
		const uint32_t num = 1u << (opt->lc + opt->lp);
		for (i = 0; i < num * LITERAL_CODER_SIZE; ++i)
			bit_reset(c->literal[i]);
	}

	c->rc.range = 0;
	c->rc.code = 0;
	c->rc.init_bytes_left = RC_INIT_BYTES;
	c->pending_len = 0;
	c->pending_dist = 0;
	c->temp_size = 0;
}

/* Decodes exactly one symbol. */
static xz_ret decode_symbol(lzma_dec *c, dict_t *dict, rc_src *s)
{
	const uint32_t pos_state = (uint32_t)dict->pos & c->pos_mask;

	if (rc_bit(s, &c->is_match[c->state][pos_state]) == 0) {
		/* Literal */
		probability *subcoder = c->literal + LITERAL_CODER_SIZE
				* literal_subcoder_index(c->literal_context_bits,
					c->literal_pos_mask, (uint32_t)dict->pos,
					dict->full > 0 || dict->pos > 0
						? dict_get(dict, 0) : 0);
		uint32_t symbol;

		if (is_lit_state(c->state)) {
			symbol = 1;
			do {
				symbol = (symbol << 1) + rc_bit(s, subcoder + symbol);
			} while (symbol < 0x100);
		} else {
			uint32_t match_byte = dict_get(dict, c->rep0);
			uint32_t offset = 0x100;
			symbol = 1;
			do {
				uint32_t match_bit;
				uint32_t subcoder_index;
				uint32_t bit;
				match_byte <<= 1;
				match_bit = match_byte & offset;
				subcoder_index = offset + match_bit + symbol;
				bit = rc_bit(s, subcoder + subcoder_index);
				symbol = (symbol << 1) + bit;
				offset &= (0u - bit) ^ ~match_bit;
			} while (symbol < 0x100);
		}

		if (s->overflow)
			return XZ_OK;
		update_literal(&c->state);
		dict_put(dict, (uint8_t)symbol);
		return XZ_OK;
	}

	{
		uint32_t len;
		if (rc_bit(s, &c->is_rep[c->state]) != 0) {
			/* Repeated match */
			if (rc_bit(s, &c->is_rep0[c->state]) == 0) {
				if (rc_bit(s, &c->is_rep0_long[c->state][pos_state])
						== 0) {
					if (s->overflow)
						return XZ_OK;
					update_short_rep(&c->state);
					if (dict->full == 0 && dict->pos == 0)
						return XZ_DATA_ERROR;
					dict_put(dict, dict_get(dict, c->rep0));
					return XZ_OK;
				}
			} else {
				uint32_t distance;
				if (rc_bit(s, &c->is_rep1[c->state]) == 0) {
					distance = c->rep1;
					c->rep1 = c->rep0;
				} else {
					if (rc_bit(s, &c->is_rep2[c->state]) == 0) {
						distance = c->rep2;
					} else {
						distance = c->rep3;
						c->rep3 = c->rep2;
					}
					c->rep2 = c->rep1;
					c->rep1 = c->rep0;
				}
				c->rep0 = distance;
			}
			len = len_decode(&c->rep_len_dec, s, pos_state);
			if (s->overflow)
				return XZ_OK;
			update_long_rep(&c->state);
		} else {
			/* Simple match */
			uint32_t dist_slot;
			c->rep3 = c->rep2;
			c->rep2 = c->rep1;
			c->rep1 = c->rep0;

			len = len_decode(&c->match_len_dec, s, pos_state);
			dist_slot = rc_bittree(s,
					c->dist_slot[get_dist_state(len)],
					DIST_SLOTS) - DIST_SLOTS;

			if (dist_slot < DIST_MODEL_START) {
				c->rep0 = dist_slot;
			} else {
				const uint32_t limit = (dist_slot >> 1) - 1;
				c->rep0 = (2 | (dist_slot & 1)) << limit;
				if (dist_slot < DIST_MODEL_END) {
					c->rep0 += rc_bittree_rev(s,
							c->pos_special + c->rep0
								- dist_slot - 1,
							limit);
				} else {
					c->rep0 += rc_direct(s, limit - ALIGN_BITS)
							<< ALIGN_BITS;
					c->rep0 += rc_bittree_rev(s, c->pos_align,
							ALIGN_BITS);
				}
			}

			if (s->overflow)
				return XZ_OK;

			update_match(&c->state);

			if (c->rep0 == UINT32_MAX) {
				/* End of payload marker */
				c->eopm_seen = true;
				return XZ_STREAM_END;
			}
		}

		if (s->overflow)
			return XZ_OK;

		if (c->rep0 >= dict->full && c->rep0 >= dict->pos)
			return XZ_DATA_ERROR;
		if ((uint64_t)c->rep0 >= dict->size)
			return XZ_DATA_ERROR;

		c->pending_len = len;
		c->pending_dist = c->rep0;
		if (!dict_repeat(dict, &c->pending_len, c->pending_dist))
			return XZ_OK;
	}

	return XZ_OK;
}

xz_ret lzma_dec_rc_init(lzma_dec *c, const uint8_t *in, size_t *in_pos,
		size_t in_size)
{
	while (c->rc.init_bytes_left > 0) {
		if (*in_pos == in_size)
			return XZ_OK;
		if (c->rc.init_bytes_left == RC_INIT_BYTES && in[*in_pos] != 0)
			return XZ_DATA_ERROR;
		c->rc.code = (c->rc.code << 8) | in[*in_pos];
		++*in_pos;
		--c->rc.init_bytes_left;
	}
	c->rc.range = UINT32_MAX;
	return XZ_STREAM_END;
}

bool lzma_dec_rc_finished(const lzma_dec *c)
{
	return c->rc.code == 0 && c->rc.init_bytes_left == 0;
}

/* Decode from a contiguous buffer. */
static xz_ret decode_buf(lzma_dec *c, dict_t *dict, const uint8_t *in,
		size_t *in_pos, size_t in_size, bool complete)
{
	rc_src s;
	xz_ret ret = XZ_OK;

	s.buf = in;
	s.pos = *in_pos;
	s.size = in_size;
	s.range = c->rc.range;
	s.code = c->rc.code;
	s.overflow = false;

	if (c->pending_len > 0) {
		if (!dict_repeat(dict, &c->pending_len, c->pending_dist))
			goto out;
	}

	while (dict->pos < dict->limit) {
		size_t start_pos = s.pos;
		size_t avail = in_size - s.pos;
		if (avail < LZMA_IN_REQUIRED && !complete)
			break;
		ret = decode_symbol(c, dict, &s);
		if (s.overflow) {
			/* Ran out of input in the middle of a symbol. */
			s.pos = start_pos;
			ret = complete ? XZ_DATA_ERROR : XZ_OK;
			break;
		}
		if (ret != XZ_OK)
			break;
		if (c->pending_len > 0)
			break;
	}

out:
	if (!s.overflow) {
		c->rc.range = s.range;
		c->rc.code = s.code;
		*in_pos = s.pos;
	} else {
		*in_pos = s.pos;
	}
	return ret;
}

xz_ret lzma_dec_run(lzma_dec *c, dict_t *dict, const uint8_t *in,
		size_t *in_pos, size_t in_size, bool eof)
{
	xz_ret ret;

	if (c->rc.init_bytes_left > 0) {
		ret = lzma_dec_rc_init(c, in, in_pos, in_size);
		if (ret == XZ_OK)
			return XZ_OK;
		if (ret != XZ_STREAM_END)
			return ret;
	}

	if (c->temp_size > 0) {
		size_t copy = sizeof(c->temp) - c->temp_size;
		size_t tpos = 0;
		size_t total;
		bool complete;

		if (copy > in_size - *in_pos)
			copy = in_size - *in_pos;
		memcpy(c->temp + c->temp_size, in + *in_pos, copy);
		total = c->temp_size + copy;
		complete = eof && (in_size - *in_pos) == copy;

		if (total < LZMA_IN_REQUIRED && !complete) {
			c->temp_size = total;
			*in_pos += copy;
			return XZ_OK;
		}

		ret = decode_buf(c, dict, c->temp, &tpos, total, complete);
		if (tpos < c->temp_size) {
			memmove(c->temp, c->temp + tpos, c->temp_size - tpos);
			c->temp_size -= tpos;
			return ret;
		}
		*in_pos += tpos - c->temp_size;
		c->temp_size = 0;
		if (ret != XZ_OK || dict->pos == dict->limit)
			return ret;
	}

	ret = decode_buf(c, dict, in, in_pos, in_size, eof);
	if (ret != XZ_OK)
		return ret;

	if (dict->pos < dict->limit && !eof) {
		size_t copy = in_size - *in_pos;
		if (copy > sizeof(c->temp))
			copy = sizeof(c->temp);
		memcpy(c->temp, in + *in_pos, copy);
		c->temp_size = copy;
		*in_pos += copy;
	}

	return XZ_OK;
}

