#ifndef XZR_LZMA_DECODER_H
#define XZR_LZMA_DECODER_H

#include "lzma_common.h"

/* Sliding-window dictionary shared by the LZMA and LZMA2 decoders. */
typedef struct {
	uint8_t *buf;
	size_t start;
	size_t pos;
	size_t full;
	size_t limit;
	size_t size;
	bool need_reset;
} dict_t;

typedef struct {
	uint32_t range;
	uint32_t code;
	uint32_t init_bytes_left;
} rc_dec;

typedef struct {
	dict_t *dictp;

	uint32_t rep0, rep1, rep2, rep3;
	uint32_t state;
	uint32_t uncompressed_size_known;
	uint64_t uncompressed_size;

	uint32_t pos_mask;
	uint32_t literal_context_bits;
	uint32_t literal_pos_mask;

	rc_dec rc;

