#include "lzma_decoder.h"
#include "filter.h"

enum lz_seq {
	SEQ_CONTROL,
	SEQ_UNCOMPRESSED_1,
	SEQ_UNCOMPRESSED_2,
	SEQ_COMPRESSED_0,
	SEQ_COMPRESSED_1,
	SEQ_PROPERTIES,
	SEQ_LZMA,
	SEQ_COPY,
	SEQ_LZMA1,
	SEQ_DONE
};

typedef struct {
	dict_t dict;
	lzma_dec lzma;
	lzma_options options;
	enum lz_seq sequence;
	enum lz_seq next_sequence;
	uint32_t uncompressed_size;
	uint32_t compressed_size;
	bool need_props;
	bool need_dict_reset;
	bool need_state_reset;
	bool lzma1;
	bool allow_eopm;
	bool size_known;
	uint64_t uncomp_left;
	bool finished;
} lz_dec;

static void lz_dec_end(void *coder_ptr)
{
	lz_dec *c = coder_ptr;
	dict_free(&c->dict);
	free(c);
}

/* Copies data from the dictionary to the output buffer. */
static void dict_flush(lz_dec *c, uint8_t *out, size_t *out_pos,
		size_t out_size)
{
	const size_t copy = c->dict.pos - c->dict.start;
	(void)out_size;
	if (copy > 0)
		memcpy(out + *out_pos, c->dict.buf + c->dict.start, copy);
	*out_pos += copy;
	c->dict.start = c->dict.pos;
	if (c->dict.pos == c->dict.size) {
		c->dict.pos = 0;
		c->dict.start = 0;
	}
}

static xz_ret lz_decode_inner(lz_dec *c, const uint8_t *in, size_t *in_pos,
		size_t in_size, bool eof)
{
	if (c->lzma1) {
		size_t chunk_start;
		xz_ret ret;
		if (c->size_known) {
			const uint64_t left = c->uncomp_left
					- (c->dict.pos - c->dict.start);
			if (c->dict.limit - c->dict.pos > left)
				c->dict.limit = c->dict.pos + (size_t)left;
		}
		chunk_start = c->dict.pos;
		ret = lzma_dec_run(&c->lzma, &c->dict, in, in_pos, in_size, eof);
		c->uncomp_left -= c->dict.pos - chunk_start;
		if (ret == XZ_STREAM_END) {
			c->finished = true;
			return XZ_STREAM_END;
		}
		if (ret != XZ_OK)
			return ret;
		if (c->size_known && c->uncomp_left == 0) {
			c->finished = true;
			return XZ_STREAM_END;
		}
		return XZ_OK;
	}

	while (true) {
		switch (c->sequence) {
		case SEQ_CONTROL: {
			uint32_t control;
			if (*in_pos >= in_size)
				return XZ_OK;
			control = in[*in_pos];
			++*in_pos;

			if (control == 0x00) {
				c->finished = true;
				return XZ_STREAM_END;
			}

			if (control >= 0xE0 || control == 0x01) {
				c->need_props = true;
				c->need_dict_reset = true;
			} else if (c->need_dict_reset) {
				return XZ_DATA_ERROR;
			}

			if (control >= 0x80) {
				c->uncompressed_size = (control & 0x1F) << 16;
				c->sequence = SEQ_UNCOMPRESSED_1;
				if (control >= 0xC0) {
					c->need_props = false;
					c->need_state_reset = false;
					c->next_sequence = SEQ_PROPERTIES;
				} else if (c->need_props) {
					return XZ_DATA_ERROR;
				} else {
					c->next_sequence = SEQ_LZMA;
					if (control >= 0xA0) {
						c->need_state_reset = false;
						lzma_dec_reset(&c->lzma,
								&c->options);
					} else if (c->need_state_reset) {
						return XZ_DATA_ERROR;
					}
				}
			} else {
				if (control > 0x02)
					return XZ_DATA_ERROR;
				c->need_state_reset = true;
				c->sequence = SEQ_COMPRESSED_0;
				c->next_sequence = SEQ_COPY;
			}

			if (c->need_dict_reset) {
				c->need_dict_reset = false;
				dict_reset(&c->dict);
				c->dict.start = 0;
			}
			break;
		}

		case SEQ_UNCOMPRESSED_1:
			if (*in_pos >= in_size)
				return XZ_OK;
			c->uncompressed_size += (uint32_t)in[(*in_pos)++] << 8;
			c->sequence = SEQ_UNCOMPRESSED_2;
			break;

		case SEQ_UNCOMPRESSED_2:
			if (*in_pos >= in_size)
				return XZ_OK;
			c->uncompressed_size += in[(*in_pos)++] + 1;
			c->sequence = SEQ_COMPRESSED_0;
			break;

		case SEQ_COMPRESSED_0:
			if (*in_pos >= in_size)
				return XZ_OK;
			c->compressed_size = (uint32_t)in[(*in_pos)++] << 8;
			c->sequence = SEQ_COMPRESSED_1;
			break;

		case SEQ_COMPRESSED_1:
			if (*in_pos >= in_size)
				return XZ_OK;
			c->compressed_size += in[(*in_pos)++] + 1;
			c->sequence = c->next_sequence;
			break;

		case SEQ_PROPERTIES:
			if (*in_pos >= in_size)
				return XZ_OK;
			if (lzma_dec_set_props(&c->options, in[(*in_pos)++]))
				return XZ_DATA_ERROR;
			lzma_dec_reset(&c->lzma, &c->options);
			c->sequence = SEQ_LZMA;
			break;

		case SEQ_LZMA: {
			size_t limit_save = c->dict.limit;
			size_t chunk_start;
			size_t sub_in_size;
			size_t sub_in_pos;
			xz_ret ret;

			if (c->dict.limit - c->dict.pos > c->uncompressed_size)
				c->dict.limit = c->dict.pos + c->uncompressed_size;

			sub_in_size = *in_pos + c->compressed_size;
			if (sub_in_size > in_size)
				sub_in_size = in_size;
			sub_in_pos = *in_pos;
			chunk_start = c->dict.pos;

			ret = lzma_dec_run(&c->lzma, &c->dict, in, &sub_in_pos,
					sub_in_size,
					sub_in_size == *in_pos + c->compressed_size);
			c->compressed_size -= (uint32_t)(sub_in_pos - *in_pos);
			c->uncompressed_size -= (uint32_t)(c->dict.pos
					- chunk_start);
			*in_pos = sub_in_pos;
			c->dict.limit = limit_save;

			if (ret == XZ_DATA_ERROR)
				return XZ_DATA_ERROR;
			if (ret == XZ_STREAM_END)
				return XZ_DATA_ERROR;

			if (c->uncompressed_size == 0) {
				if (c->compressed_size != 0
						|| !lzma_dec_rc_finished(&c->lzma))
					return XZ_DATA_ERROR;
				c->sequence = SEQ_CONTROL;
				break;
			}
			if (c->compressed_size == 0)
				return XZ_DATA_ERROR;
			return XZ_OK;
		}

		case SEQ_COPY: {
			size_t copy = in_size - *in_pos;
			if (copy > c->dict.limit - c->dict.pos)
				copy = c->dict.limit - c->dict.pos;
			if (copy > c->compressed_size)
				copy = c->compressed_size;
			if (copy > 0) {
				memcpy(c->dict.buf + c->dict.pos, in + *in_pos,
						copy);
				c->dict.pos += copy;
				if (c->dict.pos > c->dict.full)
					c->dict.full = c->dict.pos;
				*in_pos += copy;
				c->compressed_size -= (uint32_t)copy;
			}
			if (c->compressed_size == 0) {
				c->sequence = SEQ_CONTROL;
				break;
			}
			return XZ_OK;
		}

		default:
			return XZ_PROG_ERROR;
		}
	}
}

static xz_ret lz_dec_code(void *coder_ptr, const uint8_t *in, size_t *in_pos,
		size_t in_size, uint8_t *out, size_t *out_pos, size_t out_size,
		xz_action action)
{
	lz_dec *c = coder_ptr;
	const bool eof = action != ACTION_RUN;

	while (*out_pos < out_size && !c->finished) {
		size_t out_avail = out_size - *out_pos;
		size_t in_start = *in_pos;
		size_t out_before;
		xz_ret ret;

		c->dict.limit = c->dict.pos
				+ my_min64(out_avail, c->dict.size - c->dict.pos);
		out_before = c->dict.pos;

		ret = lz_decode_inner(c, in, in_pos, in_size, eof);
		dict_flush(c, out, out_pos, out_size);

		if (ret == XZ_STREAM_END)
			return XZ_STREAM_END;
		if (ret != XZ_OK)
			return ret;
		if (*in_pos == in_start && c->dict.pos == out_before
