#include "filter.h"

#define SIMPLE_BUFSIZE 4096

typedef size_t (*simple_fn)(void *state, uint32_t now_pos, bool is_encoder,
		uint8_t *buffer, size_t size);

typedef struct {
	next_coder next;
	bool is_encoder;
	bool end_reached;
	uint32_t now_pos;
	size_t pos;       /* bytes of buffer already passed on */
	size_t filtered;  /* bytes of buffer that have been transformed */
	size_t size;      /* bytes of valid data in buffer */
	simple_fn filter;
	void *state;
	uint8_t buffer[SIMPLE_BUFSIZE];
} simple_coder;

static void simple_end(void *coder_ptr)
{
	simple_coder *c = coder_ptr;
	next_end(&c->next);
	free(c->state);
	free(c);
}

static void simple_compact(simple_coder *c)
{
	if (c->pos == c->filtered && c->filtered > 0) {
		memmove(c->buffer, c->buffer + c->filtered, c->size - c->filtered);
		c->now_pos += (uint32_t)c->filtered;
		c->size -= c->filtered;
		c->pos = 0;
		c->filtered = 0;
	}
}

static xz_ret simple_code_dec(void *coder_ptr, const uint8_t *in,
		size_t *in_pos, size_t in_size, uint8_t *out, size_t *out_pos,
		size_t out_size, xz_action action)
{
	simple_coder *c = coder_ptr;

	while (true) {
		size_t copy;
		size_t buf_pos;
		xz_ret ret;

		/* Give out what has already been filtered. */
		copy = c->filtered - c->pos;
		if (copy > out_size - *out_pos)
			copy = out_size - *out_pos;
		memcpy(out + *out_pos, c->buffer + c->pos, copy);
		*out_pos += copy;
		c->pos += copy;

		if (*out_pos == out_size)
			return XZ_OK;

		simple_compact(c);
		if (c->pos != c->filtered)
			return XZ_OK;

		if (c->end_reached) {
			if (c->size == 0)
				return XZ_STREAM_END;
			/* Flush the unfilterable tail as is. */
			c->filtered = c->size;
			continue;
		}

		buf_pos = c->size;
		ret = next_code(&c->next, in, in_pos, in_size, c->buffer,
				&buf_pos, SIMPLE_BUFSIZE, action);
		if (ret == XZ_STREAM_END)
			c->end_reached = true;
		else if (ret != XZ_OK)
			return ret;

		if (buf_pos == c->size && !c->end_reached)
			return XZ_OK;
		c->size = buf_pos;

		c->filtered = c->filter(c->state, c->now_pos, false, c->buffer,
				c->size);
	}
}

static xz_ret simple_code_enc(void *coder_ptr, const uint8_t *in,
		size_t *in_pos, size_t in_size, uint8_t *out, size_t *out_pos,
		size_t out_size, xz_action action)
{
	simple_coder *c = coder_ptr;

	while (true) {
		size_t copy;
		xz_ret ret;
		bool last;

		if (c->pos < c->filtered) {
			size_t sub_pos = c->pos;
			ret = next_code(&c->next, c->buffer, &sub_pos,
					c->filtered, out, out_pos, out_size,
					(c->end_reached && c->filtered == c->size)
						? action : ACTION_RUN);
			c->pos = sub_pos;
			if (ret != XZ_OK)
				return ret;
			if (c->pos < c->filtered)
				return XZ_OK;
		}

		simple_compact(c);

		if (c->end_reached && c->size == 0) {
			size_t dummy = 0;
			return next_code(&c->next, c->buffer, &dummy, 0, out,
					out_pos, out_size, action);
		}

		copy = SIMPLE_BUFSIZE - c->size;
		if (copy > in_size - *in_pos)
			copy = in_size - *in_pos;
		memcpy(c->buffer + c->size, in + *in_pos, copy);
		*in_pos += copy;
		c->size += copy;

		last = action != ACTION_RUN && *in_pos == in_size;
		if (last)
			c->end_reached = true;

		c->filtered = c->filter(c->state, c->now_pos, true, c->buffer,
