		if (c->filtered == 0) {
			if (c->end_reached)
				continue;
			return XZ_OK;
		}
	}
}

static xz_ret simple_coder_init(next_coder *next, const next_coder *sub,
		bool is_encoder, simple_fn filter, void *state,
		uint32_t start_offset)
{
	simple_coder *c = calloc(1, sizeof(simple_coder));
	if (c == NULL) {
