#include "filter.h"

bool filter_is_supported_dec(uint64_t id)
{
	switch (id) {
	case FILTER_DELTA:
	case FILTER_X86:
	case FILTER_POWERPC:
	case FILTER_IA64:
	case FILTER_ARM:
	case FILTER_ARMTHUMB:
	case FILTER_SPARC:
	case FILTER_ARM64:
	case FILTER_RISCV:
	case FILTER_LZMA1:
	case FILTER_LZMA2:
		return true;
	default:
		return false;
	}
}

bool filter_is_supported_enc(uint64_t id)
{
	return filter_is_supported_dec(id);
}

static bool is_last_filter(uint64_t id)
{
	return id == FILTER_LZMA1 || id == FILTER_LZMA2;
}

xz_ret raw_decoder_init(next_coder *next, const filter_info *filters,
		size_t count)
{
	size_t i;
	next_coder cur = NEXT_CODER_INIT;
	next_coder tmp;
	xz_ret ret;

	if (count == 0 || count > FILTERS_MAX)
		return XZ_OPTIONS_ERROR;

	for (i = 0; i < count; ++i) {
		if (!filter_is_supported_dec(filters[i].id))
			return XZ_OPTIONS_ERROR;
		if (is_last_filter(filters[i].id) != (i == count - 1))
			return XZ_OPTIONS_ERROR;
	}

	/* Build from the innermost (last) filter outwards. */
	for (i = count; i-- > 0; ) {
		const filter_info *f = &filters[i];
		tmp = cur;
		switch (f->id) {
		case FILTER_LZMA2:
			ret = lzma2_decoder_init(&cur, &tmp, f->options);
			break;
		case FILTER_LZMA1:
			ret = lzma1_decoder_init(&cur, &tmp, f->options,
					VLI_UNKNOWN, true);
			break;
		case FILTER_DELTA:
			ret = delta_decoder_init(&cur, &tmp, f->options);
			break;
		default:
			ret = bcj_decoder_init(&cur, &tmp, f->id, f->options);
			break;
		}
		if (ret != XZ_OK) {
			next_end(&cur);
			return ret;
		}
	}

	*next = cur;
	return XZ_OK;
}

xz_ret raw_encoder_init(next_coder *next, const filter_info *filters,
		size_t count)
{
	size_t i;
	next_coder cur = NEXT_CODER_INIT;
	next_coder tmp;
	xz_ret ret;

	if (count == 0 || count > FILTERS_MAX)
		return XZ_OPTIONS_ERROR;

	for (i = 0; i < count; ++i) {
		if (!filter_is_supported_enc(filters[i].id))
			return XZ_OPTIONS_ERROR;
		if (is_last_filter(filters[i].id) != (i == count - 1))
			return XZ_OPTIONS_ERROR;
	}

	for (i = count; i-- > 0; ) {
		const filter_info *f = &filters[i];
		tmp = cur;
		switch (f->id) {
		case FILTER_LZMA2:
			ret = lzma2_encoder_init(&cur, &tmp, f->options);
			break;
		case FILTER_LZMA1:
			ret = lzma1_encoder_init(&cur, &tmp, f->options);
			break;
		case FILTER_DELTA:
			ret = delta_encoder_init(&cur, &tmp, f->options);
			break;
		default:
			ret = bcj_encoder_init(&cur, &tmp, f->id, f->options);
			break;
		}
		if (ret != XZ_OK) {
			next_end(&cur);
			return ret;
		}
	}

	*next = cur;
	return XZ_OK;
}

/* -------- filter properties -------- */

static uint32_t lzma2_dict_size_prop(uint32_t dict_size)
{
	uint32_t i;
	for (i = 0; i < 40; ++i) {
		uint32_t d = i & 1 ? (3u << (i / 2 + 11)) : (2u << (i / 2 + 11));
		if (dict_size <= d)
			return i;
	}
	return 40;
}

xz_ret filter_props_size(uint32_t *size, uint64_t id, const void *options)
{
	switch (id) {
	case FILTER_LZMA1:
		*size = 5;
		return XZ_OK;
	case FILTER_LZMA2:
		*size = 1;
		return XZ_OK;
	case FILTER_DELTA:
		*size = 1;
		return XZ_OK;
	default: {
		const bcj_options *opt = options;
		if (opt != NULL && opt->start_offset != 0)
			*size = 4;
		else
			*size = 0;
		return XZ_OK;
	}
	}
}

xz_ret filter_props_encode(uint64_t id, const void *options, uint8_t *out)
{
	switch (id) {
	case FILTER_LZMA1: {
		const lzma_options *opt = options;
		if (opt->lc + opt->lp > 4 || opt->pb > 4)
