#include "filter.h"

bool filter_is_supported_dec(uint64_t id)
{
	switch (id) {
	case FILTER_DELTA:
	case FILTER_X86:
	case FILTER_POWERPC:
	case FILTER_IA64:
	case FILTER_ARM:
	case FILTER_ARMTHUMB:
	case FILTER_SPARC:
	case FILTER_ARM64:
	case FILTER_RISCV:
	case FILTER_LZMA1:
	case FILTER_LZMA2:
		return true;
	default:
		return false;
	}
}

bool filter_is_supported_enc(uint64_t id)
{
	return filter_is_supported_dec(id);
}

static bool is_last_filter(uint64_t id)
{
	return id == FILTER_LZMA1 || id == FILTER_LZMA2;
}

xz_ret raw_decoder_init(next_coder *next, const filter_info *filters,
		size_t count)
{
	size_t i;
	next_coder cur = NEXT_CODER_INIT;
	next_coder tmp;
	xz_ret ret;

	if (count == 0 || count > FILTERS_MAX)
		return XZ_OPTIONS_ERROR;

	for (i = 0; i < count; ++i) {
		if (!filter_is_supported_dec(filters[i].id))
			return XZ_OPTIONS_ERROR;
		if (is_last_filter(filters[i].id) != (i == count - 1))
			return XZ_OPTIONS_ERROR;
	}

	/* Build from the innermost (last) filter outwards. */
	for (i = count; i-- > 0; ) {
		const filter_info *f = &filters[i];
		tmp = cur;
		switch (f->id) {
		case FILTER_LZMA2:
			ret = lzma2_decoder_init(&cur, &tmp, f->options);
			break;
		case FILTER_LZMA1:
			ret = lzma1_decoder_init(&cur, &tmp, f->options,
					VLI_UNKNOWN, true);
			break;
		case FILTER_DELTA:
			ret = delta_decoder_init(&cur, &tmp, f->options);
			break;
		default:
			ret = bcj_decoder_init(&cur, &tmp, f->id, f->options);
			break;
		}
		if (ret != XZ_OK) {
			next_end(&cur);
			return ret;
		}
	}

	*next = cur;
	return XZ_OK;
}

xz_ret raw_encoder_init(next_coder *next, const filter_info *filters,
		size_t count)
{
	size_t i;
	next_coder cur = NEXT_CODER_INIT;
	next_coder tmp;
	xz_ret ret;

	if (count == 0 || count > FILTERS_MAX)
		return XZ_OPTIONS_ERROR;

	for (i = 0; i < count; ++i) {
		if (!filter_is_supported_enc(filters[i].id))
			return XZ_OPTIONS_ERROR;
		if (is_last_filter(filters[i].id) != (i == count - 1))
			return XZ_OPTIONS_ERROR;
	}

	for (i = count; i-- > 0; ) {
		const filter_info *f = &filters[i];
		tmp = cur;
		switch (f->id) {
		case FILTER_LZMA2:
			ret = lzma2_encoder_init(&cur, &tmp, f->options);
			break;
		case FILTER_LZMA1:
			ret = lzma1_encoder_init(&cur, &tmp, f->options);
			break;
		case FILTER_DELTA:
			ret = delta_encoder_init(&cur, &tmp, f->options);
			break;
		default:
			ret = bcj_encoder_init(&cur, &tmp, f->id, f->options);
			break;
		}
		if (ret != XZ_OK) {
			next_end(&cur);
			return ret;
		}
	}

	*next = cur;
	return XZ_OK;
}

