#ifndef XZR_STREAM_H
#define XZR_STREAM_H

#include "common.h"
#include "filter.h"

#define STREAM_HEADER_SIZE 12

typedef struct {
	uint64_t unpadded_size;
	uint64_t uncompressed_size;
} index_record;

typedef struct {
	index_record *records;
	size_t count;
	size_t alloc;
	uint64_t blocks_size;      /* sum of padded block total sizes */
	uint64_t uncompressed_size;
} index_t;

extern void index_init(index_t *i);
extern void index_free(index_t *i);
extern bool index_append(index_t *i, uint64_t unpadded, uint64_t uncomp);
extern uint64_t index_size(const index_t *i);
extern uint64_t index_stream_size(const index_t *i);

/* Block header info */
typedef struct {
	uint32_t header_size;
	uint32_t check_type;
	uint64_t compressed_size;
	uint64_t uncompressed_size;
	filter_info filters[FILTERS_MAX + 1];
	size_t filter_count;
	bool ignore_check;
} block_info;

extern void block_free_filters(block_info *b);

/* Stream decoder flags */
#define DEC_CONCATENATED 0x08
#define DEC_TELL_NO_CHECK 0x01
#define DEC_TELL_UNSUPPORTED_CHECK 0x02
#define DEC_IGNORE_CHECK 0x10

typedef struct stream_dec_s stream_dec;

extern stream_dec *stream_dec_init(uint64_t memlimit, uint32_t flags);
extern void stream_dec_free(stream_dec *s);
extern xz_ret stream_dec_code(stream_dec *s, const uint8_t *in, size_t *in_pos,
