#include "stream.h"

void index_init(index_t *i)
{
	memset(i, 0, sizeof(*i));
}

void index_free(index_t *i)
{
	free(i->records);
	i->records = NULL;
	i->count = 0;
	i->alloc = 0;
}

bool index_append(index_t *i, uint64_t unpadded, uint64_t uncomp)
{
	if (i->count == i->alloc) {
		const size_t n = i->alloc == 0 ? 64 : i->alloc * 2;
		index_record *r = realloc(i->records, n * sizeof(index_record));
		if (r == NULL)
			return true;
		i->records = r;
		i->alloc = n;
	}
	i->records[i->count].unpadded_size = unpadded;
	i->records[i->count].uncompressed_size = uncomp;
	++i->count;
	i->blocks_size += (unpadded + 3) & ~UINT64_C(3);
	i->uncompressed_size += uncomp;
	return false;
}

uint64_t index_size(const index_t *i)
{
	uint64_t size = 1 + vli_size(i->count);
	size_t k;
	for (k = 0; k < i->count; ++k)
		size += vli_size(i->records[k].unpadded_size)
				+ vli_size(i->records[k].uncompressed_size);
	size = (size + 3) & ~UINT64_C(3);
	return size + 4;
}

uint64_t index_stream_size(const index_t *i)
{
	return STREAM_HEADER_SIZE + i->blocks_size + index_size(i)
			+ STREAM_HEADER_SIZE;
}

void block_free_filters(block_info *b)
{
	size_t i;
	for (i = 0; i < b->filter_count; ++i) {
		free(b->filters[i].options);
		b->filters[i].options = NULL;
	}
	b->filter_count = 0;
}

