#include "stream.h"
#include "lzma_decoder.h"

static const uint8_t XZ_MAGIC[6] = { 0xFD, '7', 'z', 'X', 'Z', 0x00 };
static const uint8_t XZ_FOOTER_MAGIC[2] = { 'Y', 'Z' };

/* ---------------- check helper ---------------- */

typedef struct {
	uint32_t type;
	uint32_t crc32;
	uint64_t crc64;
	sha256_state sha;
} check_state;

static void check_start(check_state *c, uint32_t type)
{
	c->type = type;
	c->crc32 = 0;
	c->crc64 = 0;
	if (type == CHECK_SHA256)
		sha256_init(&c->sha);
}

static void check_update(check_state *c, const uint8_t *buf, size_t size)
{
	switch (c->type) {
	case CHECK_CRC32:
		c->crc32 = xcrc32(buf, size, c->crc32);
		break;
	case CHECK_CRC64:
		c->crc64 = xcrc64(buf, size, c->crc64);
		break;
	case CHECK_SHA256:
		sha256_update(&c->sha, buf, size);
		break;
	default:
		break;
	}
}

static void check_final(check_state *c, uint8_t *out)
{
	switch (c->type) {
	case CHECK_CRC32:
		write32le(out, c->crc32);
		break;
	case CHECK_CRC64:
		write64le(out, c->crc64);
		break;
	case CHECK_SHA256:
		sha256_finish(&c->sha, out);
		break;
	default:
		break;
	}
}

/* ---------------- block header ---------------- */

uint64_t raw_decoder_memusage(const filter_info *filters, size_t count)
{
	uint64_t total = 0;
	size_t i;
	for (i = 0; i < count; ++i) {
		switch (filters[i].id) {
		case FILTER_LZMA2: {
			const lzma_options *o = filters[i].options;
			total += (uint64_t)o->dict_size + 66200;
			break;
		}
		case FILTER_LZMA1: {
			const lzma_options *o = filters[i].options;
			total += (uint64_t)o->dict_size + 66016;
			break;
		}
		case FILTER_DELTA:
			total += 352;
			break;
		default:
			total += 1024;
			break;
		}
	}
	return total;
}

/* Parses a Block Header that is already fully in memory (including CRC32). */
xz_ret block_header_decode(block_info *b, const uint8_t *in)
{
	const size_t header_size = b->header_size;
	size_t pos = 2;
	size_t i;
	size_t count;

	if (xcrc32(in, header_size - 4, 0) != read32le(in + header_size - 4))
		return XZ_DATA_ERROR;

	if (in[1] & 0x3C)
		return XZ_OPTIONS_ERROR;

	count = (size_t)(in[1] & 0x03) + 1;

	b->compressed_size = VLI_UNKNOWN;
	b->uncompressed_size = VLI_UNKNOWN;

	if (in[1] & 0x40) {
		if (vli_decode(&b->compressed_size, NULL, in, &pos,
				header_size - 4) != XZ_OK)
			return XZ_DATA_ERROR;
		if (b->compressed_size == 0
				|| b->compressed_size > VLI_MAX)
			return XZ_DATA_ERROR;
	}
	if (in[1] & 0x80) {
		if (vli_decode(&b->uncompressed_size, NULL, in, &pos,
				header_size - 4) != XZ_OK)
			return XZ_DATA_ERROR;
	}

	b->filter_count = 0;
	for (i = 0; i < count; ++i) {
		uint64_t id;
		uint64_t props_size;
		xz_ret ret;

		if (vli_decode(&id, NULL, in, &pos, header_size - 4) != XZ_OK)
			goto data_error;
		if (vli_decode(&props_size, NULL, in, &pos, header_size - 4)
				!= XZ_OK)
			goto data_error;
		if (props_size > header_size - 4 - pos)
			goto data_error;
		if (id >= FILTER_LZMA2 && !filter_is_supported_dec(id)) {
			/* Unsupported but syntactically valid filter. */
			b->filters[i].id = id;
			b->filters[i].options = NULL;
			b->filter_count = i + 1;
			pos += (size_t)props_size;
			continue;
		}
		if (!filter_is_supported_dec(id)) {
			b->filters[i].id = id;
			b->filters[i].options = NULL;
			b->filter_count = i + 1;
			pos += (size_t)props_size;
			continue;
		}
		ret = filter_props_decode(&b->filters[i].options, id,
				in + pos, (size_t)props_size);
		b->filters[i].id = id;
		b->filter_count = i + 1;
		if (ret != XZ_OK)
			return ret;
		pos += (size_t)props_size;
	}

	for (; pos < header_size - 4; ++pos)
		if (in[pos] != 0x00)
			goto opt_error;

	return XZ_OK;

data_error:
	block_free_filters(b);
	return XZ_DATA_ERROR;
opt_error:
	block_free_filters(b);
	return XZ_OPTIONS_ERROR;
}

/* ---------------- block decoder ---------------- */

typedef struct {
	next_coder next;
	uint64_t compressed_size;
	uint64_t uncompressed_size;
	uint64_t comp_pos;
	uint64_t uncomp_pos;
	check_state check;
	bool ignore_check;
	uint32_t check_type;
	uint8_t check_buf[CHECK_SIZE_MAX];
	size_t check_pos;
	int seq;
	uint32_t padding_left;
} block_dec;

static void block_dec_end(block_dec *b)
{
	next_end(&b->next);
}

static xz_ret block_dec_init(block_dec *b, const block_info *info,
		uint32_t check_type, bool ignore_check)
{
	xz_ret ret;
	memset(b, 0, sizeof(*b));
	b->compressed_size = info->compressed_size;
	b->uncompressed_size = info->uncompressed_size;
	b->check_type = check_type;
	b->ignore_check = ignore_check;
	check_start(&b->check, check_type);
	ret = raw_decoder_init(&b->next, info->filters, info->filter_count);
	return ret;
}

static xz_ret block_dec_code(block_dec *b, const uint8_t *in, size_t *in_pos,
		size_t in_size, uint8_t *out, size_t *out_pos, size_t out_size,
		xz_action action)
{
	while (true) {
		switch (b->seq) {
		case 0: {
			const size_t out_start = *out_pos;
			size_t in_start = *in_pos;
			size_t in_avail = in_size - *in_pos;
			size_t sub_in_size;
			xz_ret ret;

			if (b->compressed_size != VLI_UNKNOWN) {
				const uint64_t left = b->compressed_size
						- b->comp_pos;
				if (in_avail > left)
					in_avail = (size_t)left;
			}
			sub_in_size = *in_pos + in_avail;

			ret = next_code(&b->next, in, in_pos, sub_in_size, out,
					out_pos, out_size, action);
			b->comp_pos += *in_pos - in_start;
			b->uncomp_pos += *out_pos - out_start;
			check_update(&b->check, out + out_start,
					*out_pos - out_start);

			if (b->uncompressed_size != VLI_UNKNOWN
					&& b->uncomp_pos > b->uncompressed_size)
				return XZ_DATA_ERROR;
			if (b->compressed_size != VLI_UNKNOWN
					&& b->comp_pos > b->compressed_size)
				return XZ_DATA_ERROR;

			if (ret == XZ_STREAM_END) {
				if ((b->compressed_size != VLI_UNKNOWN
						&& b->comp_pos
							!= b->compressed_size)
					|| (b->uncompressed_size != VLI_UNKNOWN
						&& b->uncomp_pos
							!= b->uncompressed_size))
					return XZ_DATA_ERROR;
				b->padding_left = (uint32_t)
						((4 - (b->comp_pos & 3)) & 3);
				b->seq = 1;
				break;
			}
			if (ret != XZ_OK)
				return ret;
			return XZ_OK;
		}

		case 1:
			while (b->padding_left > 0) {
				if (*in_pos >= in_size)
					return XZ_OK;
				if (in[*in_pos] != 0x00)
					return XZ_DATA_ERROR;
				++*in_pos;
				--b->padding_left;
			}
			b->seq = 2;
			break;

		case 2: {
			const size_t size = check_size(b->check_type);
			uint8_t computed[CHECK_SIZE_MAX];
			while (b->check_pos < size) {
				if (*in_pos >= in_size)
					return XZ_OK;
				b->check_buf[b->check_pos++] = in[(*in_pos)++];
			}
			if (size > 0 && !b->ignore_check) {
				check_final(&b->check, computed);
				if (memcmp(computed, b->check_buf, size) != 0)
					return XZ_DATA_ERROR;
			}
			return XZ_STREAM_END;
		}

		default:
			return XZ_PROG_ERROR;
		}
	}
}

/* ---------------- stream decoder ---------------- */

enum {
	S_HEADER,
	S_BLOCK_HEADER_SIZE,
	S_BLOCK_HEADER,
	S_BLOCK,
	S_INDEX,
	S_INDEX_PADDING,
	S_INDEX_CRC32,
	S_FOOTER,
	S_PADDING,
	S_DONE
};

struct stream_dec_s {
	int seq;
	uint32_t flags;
	uint64_t memlimit;
	uint64_t memusage;
	uint64_t memlimit_needed;

	uint32_t check_type;
	uint8_t header[STREAM_HEADER_SIZE];
	size_t pos;

	uint8_t block_header[1024];
	size_t block_header_size;

	block_info binfo;
	block_dec block;
	bool block_active;

	index_t index;
	size_t index_count_expected;
	uint64_t index_count;
	uint64_t index_vli;
	size_t index_vli_pos;
	int index_field;
	uint64_t index_unpadded;
	uint32_t index_crc;
	uint64_t index_size_so_far;
	uint32_t index_padding;

	uint64_t observed_blocks_size;
	uint64_t observed_uncomp;
	uint64_t observed_count;

	uint32_t footer_crc;
	bool first_stream;
	bool tell_no_check_done;
};

stream_dec *stream_dec_init(uint64_t memlimit, uint32_t flags)
{
	stream_dec *s = calloc(1, sizeof(stream_dec));
	if (s == NULL)
		return NULL;
	s->memlimit = memlimit == 0 ? 1 : memlimit;
	s->flags = flags;
	s->seq = S_HEADER;
	s->first_stream = true;
	index_init(&s->index);
	return s;
}

void stream_dec_free(stream_dec *s)
{
	if (s == NULL)
		return;
	if (s->block_active)
		block_dec_end(&s->block);
	block_free_filters(&s->binfo);
	index_free(&s->index);
	free(s);
}

uint64_t stream_dec_memusage(const stream_dec *s) { return s->memusage; }
uint64_t stream_dec_memlimit_needed(const stream_dec *s)
{
	return s->memlimit_needed;
}
uint32_t stream_dec_check(const stream_dec *s) { return s->check_type; }
void stream_dec_set_memlimit(stream_dec *s, uint64_t limit)
{
	s->memlimit = limit;
}

static xz_ret parse_stream_header(stream_dec *s, const uint8_t *buf)
{
	if (memcmp(buf, XZ_MAGIC, 6) != 0)
		return XZ_FORMAT_ERROR;
	if (xcrc32(buf + 6, 2, 0) != read32le(buf + 8))
		return XZ_DATA_ERROR;
	if (buf[6] != 0x00 || (buf[7] & 0xF0) != 0)
		return XZ_OPTIONS_ERROR;
	s->check_type = buf[7] & 0x0F;
	return XZ_OK;
}

xz_ret stream_dec_code(stream_dec *s, const uint8_t *in, size_t *in_pos,
		size_t in_size, uint8_t *out, size_t *out_pos, size_t out_size,
		xz_action action)
{
	while (true) {
		switch (s->seq) {
		case S_HEADER: {
			xz_ret ret;
			while (s->pos < STREAM_HEADER_SIZE) {
				if (*in_pos >= in_size)
					return XZ_OK;
				s->header[s->pos++] = in[(*in_pos)++];
			}
			s->pos = 0;
			ret = parse_stream_header(s, s->header);
			if (ret != XZ_OK)
				return ret;
			s->seq = S_BLOCK_HEADER_SIZE;

			if (check_size(s->check_type) == 0
					&& (s->flags & DEC_TELL_NO_CHECK))
				return XZ_NO_CHECK;
			if (s->check_type > CHECK_SHA256
					|| (s->check_type != CHECK_NONE
						&& s->check_type != CHECK_CRC32
						&& s->check_type != CHECK_CRC64
						&& s->check_type != CHECK_SHA256))
				if (s->flags & DEC_TELL_UNSUPPORTED_CHECK)
					return XZ_UNSUPPORTED_CHECK;
			break;
		}

		case S_BLOCK_HEADER_SIZE:
			if (*in_pos >= in_size)
				return XZ_OK;
			if (in[*in_pos] == 0x00) {
				s->seq = S_INDEX;
				s->index_size_so_far = 1;
				s->index_crc = xcrc32(in + *in_pos, 1, 0);
				++*in_pos;
				s->index_vli_pos = 0;
				s->index_field = 0;
				break;
			}
			s->block_header_size = ((size_t)in[*in_pos] + 1) * 4;
			s->block_header[0] = in[(*in_pos)++];
			s->pos = 1;
			s->seq = S_BLOCK_HEADER;
			break;

		case S_BLOCK_HEADER: {
			xz_ret ret;
			uint64_t memusage;
			while (s->pos < s->block_header_size) {
				if (*in_pos >= in_size)
					return XZ_OK;
				s->block_header[s->pos++] = in[(*in_pos)++];
			}
			s->pos = 0;
			block_free_filters(&s->binfo);
			s->binfo.header_size = (uint32_t)s->block_header_size;
			ret = block_header_decode(&s->binfo, s->block_header);
			if (ret != XZ_OK)
				return ret;
			{
				size_t i;
				for (i = 0; i < s->binfo.filter_count; ++i)
					if (!filter_is_supported_dec(
							s->binfo.filters[i].id))
						return XZ_OPTIONS_ERROR;
			}
			memusage = raw_decoder_memusage(s->binfo.filters,
					s->binfo.filter_count);
			if (memusage > s->memusage)
				s->memusage = memusage;
			if (memusage > s->memlimit) {
				s->memlimit_needed = memusage;
				return XZ_MEMLIMIT_ERROR;
			}
			ret = block_dec_init(&s->block, &s->binfo,
					s->check_type,
					(s->flags & DEC_IGNORE_CHECK) != 0);
			if (ret != XZ_OK)
				return ret;
			s->block_active = true;
			s->seq = S_BLOCK;
			break;
		}

		case S_BLOCK: {
			const uint64_t comp_before = s->block.comp_pos;
			const uint64_t uncomp_before = s->block.uncomp_pos;
			xz_ret ret = block_dec_code(&s->block, in, in_pos,
					in_size, out, out_pos, out_size, action);
			(void)comp_before;
			(void)uncomp_before;
			if (ret == XZ_STREAM_END) {
				const uint64_t unpadded = s->binfo.header_size
						+ s->block.comp_pos
						+ check_size(s->check_type);
				if (index_append(&s->index, unpadded,
						s->block.uncomp_pos))
					return XZ_MEM_ERROR;
				block_dec_end(&s->block);
				s->block_active = false;
				s->seq = S_BLOCK_HEADER_SIZE;
				break;
			}
			return ret;
		}

		case S_INDEX: {
			/* Decode Number of Records and the records. */
			while (true) {
				uint8_t byte;
				xz_ret vret;
				if (*in_pos >= in_size)
					return XZ_OK;
				byte = in[*in_pos];
				vret = vli_decode(&s->index_vli,
						&s->index_vli_pos, in, in_pos,
						*in_pos + 1);
				s->index_crc = xcrc32(&byte, 1, s->index_crc);
				++s->index_size_so_far;
				if (vret == XZ_OK)
					continue;
				if (vret != XZ_STREAM_END)
					return XZ_DATA_ERROR;
				s->index_vli_pos = 0;

				if (s->index_field == 0) {
					s->index_count_expected =
							(size_t)s->index_vli;
					if (s->index_vli != s->index.count)
						return XZ_DATA_ERROR;
					if (s->index.count == 0) {
						s->seq = S_INDEX_PADDING;
						break;
					}
					s->index_count = 0;
					s->index_field = 1;
				} else if (s->index_field == 1) {
					s->index_unpadded = s->index_vli;
					s->index_field = 2;
				} else {
					const index_record *r =
						&s->index.records[s->index_count];
					if (r->unpadded_size != s->index_unpadded
							|| r->uncompressed_size
								!= s->index_vli)
						return XZ_DATA_ERROR;
					++s->index_count;
					s->index_field = 1;
					if (s->index_count == s->index.count) {
						s->seq = S_INDEX_PADDING;
						break;
					}
				}
				s->index_vli = 0;
			}
			s->index_vli = 0;
			break;
		}

		case S_INDEX_PADDING:
			while ((s->index_size_so_far & 3) != 0) {
				if (*in_pos >= in_size)
					return XZ_OK;
				if (in[*in_pos] != 0x00)
					return XZ_DATA_ERROR;
				s->index_crc = xcrc32(in + *in_pos, 1,
						s->index_crc);
				++*in_pos;
				++s->index_size_so_far;
			}
			s->pos = 0;
			s->seq = S_INDEX_CRC32;
			break;

		case S_INDEX_CRC32:
			while (s->pos < 4) {
				if (*in_pos >= in_size)
					return XZ_OK;
				s->header[s->pos++] = in[(*in_pos)++];
			}
			s->pos = 0;
			if (read32le(s->header) != s->index_crc)
				return XZ_DATA_ERROR;
			s->index_size_so_far += 4;
			s->seq = S_FOOTER;
			break;

		case S_FOOTER: {
			uint64_t backward;
			while (s->pos < STREAM_HEADER_SIZE) {
				if (*in_pos >= in_size)
					return XZ_OK;
				s->header[s->pos++] = in[(*in_pos)++];
			}
			s->pos = 0;
			if (memcmp(s->header + 10, XZ_FOOTER_MAGIC, 2) != 0)
				return XZ_DATA_ERROR;
			if (xcrc32(s->header + 4, 6, 0) != read32le(s->header))
				return XZ_DATA_ERROR;
			backward = ((uint64_t)read32le(s->header + 4) + 1) * 4;
			if (backward != s->index_size_so_far)
				return XZ_DATA_ERROR;
			if (s->header[8] != 0x00
					|| s->header[9] != s->check_type)
				return XZ_DATA_ERROR;

			if (!(s->flags & DEC_CONCATENATED)) {
				s->seq = S_DONE;
				return XZ_STREAM_END;
			}
			s->seq = S_PADDING;
			s->pos = 0;
			break;
		}

		case S_PADDING:
			while (*in_pos < in_size) {
				if (in[*in_pos] != 0x00) {
					if ((s->pos & 3) != 0)
						return XZ_DATA_ERROR;
					s->pos = 0;
					index_free(&s->index);
					index_init(&s->index);
					s->index_count = 0;
					s->index_field = 0;
					s->index_vli = 0;
					s->index_vli_pos = 0;
					s->seq = S_HEADER;
					goto next_stream;
				}
				++*in_pos;
				++s->pos;
			}
			if (action == ACTION_RUN)
				return XZ_OK;
			if ((s->pos & 3) != 0)
				return XZ_DATA_ERROR;
			s->seq = S_DONE;
			return XZ_STREAM_END;

		case S_DONE:
			return XZ_STREAM_END;

		default:
			return XZ_PROG_ERROR;
		}
		continue;
next_stream:
		continue;
	}
}

