			s->uncompressed_size, true);
	if (ret != XZ_OK)
		return ret;
	s->have_next = true;
	s->seq = A_CODE;
	return XZ_OK;
}

xz_ret alone_dec_code(alone_dec *s, const uint8_t *in, size_t *in_pos,
		size_t in_size, uint8_t *out, size_t *out_pos, size_t out_size,
		xz_action action)
{
	while (true) {
		switch (s->seq) {
		case A_PROPS:
			if (*in_pos >= in_size)
				return XZ_OK;
			if (lzma_dec_set_props(&s->options, in[(*in_pos)++]))
				return XZ_FORMAT_ERROR;
			s->pos = 0;
			s->options.dict_size = 0;
			s->seq = A_DICT;
			break;

		case A_DICT:
			while (s->pos < 4) {
				if (*in_pos >= in_size)
					return XZ_OK;
				s->options.dict_size |= (uint32_t)
						in[(*in_pos)++] << (s->pos * 8);
				++s->pos;
			}
			if (s->options.dict_size != UINT32_MAX) {
				uint32_t d = s->options.dict_size - 1;
				d |= d >> 2;
				d |= d >> 3;
				d |= d >> 4;
				d |= d >> 8;
				d |= d >> 16;
				++d;
				if (d != s->options.dict_size)
					return XZ_FORMAT_ERROR;
			}
			s->pos = 0;
			s->uncompressed_size = 0;
			s->seq = A_SIZE;
			break;

		case A_SIZE:
			while (s->pos < 8) {
				if (*in_pos >= in_size)
					return XZ_OK;
				s->uncompressed_size |= (uint64_t)
						in[(*in_pos)++] << (s->pos * 8);
				++s->pos;
			}
			s->pos = 0;
			if (s->uncompressed_size != UINT64_MAX
					&& s->uncompressed_size
						>= (UINT64_C(1) << 38))
				return XZ_FORMAT_ERROR;
			if (s->uncompressed_size == UINT64_MAX)
				s->uncompressed_size = VLI_UNKNOWN;
			if (s->options.dict_size < DICT_SIZE_MIN)
				s->options.dict_size = DICT_SIZE_MIN;
			return alone_start(s) == XZ_OK
					? alone_dec_code(s, in, in_pos, in_size,
						out, out_pos, out_size, action)
					: (s->memusage > s->memlimit
						? XZ_MEMLIMIT_ERROR
						: XZ_PROG_ERROR);

		case A_LZIP_MAGIC:
			while (s->pos < 5) {
				if (*in_pos >= in_size)
					return XZ_OK;
				s->buf[s->pos++] = in[(*in_pos)++];
			}
			if (memcmp(s->buf, "LZIP", 4) != 0)
				return XZ_FORMAT_ERROR;
			if (s->buf[4] != 0 && s->buf[4] != 1)
				return XZ_OPTIONS_ERROR;
			s->lzip_version = s->buf[4];
			s->pos = 0;
			s->seq = A_LZIP_DICT;
			break;

		case A_LZIP_DICT: {
			uint32_t b;
			uint32_t ds;
			if (*in_pos >= in_size)
				return XZ_OK;
			b = in[(*in_pos)++];
			if ((b & 0x1F) > 29)
				return XZ_DATA_ERROR;
			ds = UINT32_C(1) << (b & 0x1F);
			ds -= (ds / 16) * ((b >> 5) & 7);
			if (ds < 4096 || ds > (UINT32_C(1) << 29))
				return XZ_DATA_ERROR;
			s->options.dict_size = ds;
			s->options.lc = 3;
			s->options.lp = 0;
			s->options.pb = 2;
			s->uncompressed_size = VLI_UNKNOWN;
			s->crc = 0;
			s->out_size = 0;
			s->member_size = 6;
			{
				xz_ret ret = alone_start(s);
				if (ret != XZ_OK)
					return ret;
			}
			break;
		}

		case A_CODE: {
			const size_t in_start = *in_pos;
			const size_t out_start = *out_pos;
			xz_ret ret = next_code(&s->next, in, in_pos, in_size,
					out, out_pos, out_size, action);
			if (s->lzip) {
				s->crc = xcrc32(out + out_start,
						*out_pos - out_start, s->crc);
				s->out_size += *out_pos - out_start;
				s->member_size += *in_pos - in_start;
			}
			if (ret != XZ_STREAM_END)
				return ret;
			if (!s->lzip) {
				s->seq = A_DONE;
				return XZ_STREAM_END;
			}
			next_end(&s->next);
			s->have_next = false;
			s->pos = 0;
			s->seq = A_LZIP_TRAILER;
			break;
		}

		case A_LZIP_TRAILER: {
			const size_t need = s->lzip_version == 0 ? 12 : 20;
			while (s->pos < need) {
				if (*in_pos >= in_size)
					return XZ_OK;
				s->buf[s->pos++] = in[(*in_pos)++];
			}
			if (read32le(s->buf) != s->crc)
				return XZ_DATA_ERROR;
			if (read64le(s->buf + 4) != s->out_size)
				return XZ_DATA_ERROR;
			s->member_size += need;
			if (need == 20 && read64le(s->buf + 12) != s->member_size)
				return XZ_DATA_ERROR;
			s->pos = 0;
			s->seq = A_LZIP_NEXT;
			break;
		}

		case A_LZIP_NEXT:
			if (*in_pos >= in_size) {
				if (action == ACTION_RUN)
					return XZ_OK;
				s->seq = A_DONE;
				return XZ_STREAM_END;
			}
			s->seq = A_LZIP_MAGIC;
			s->pos = 0;
			break;

		case A_DONE:
			return XZ_STREAM_END;

		default:
			return XZ_PROG_ERROR;
		}
	}
}

