{
	static uint8_t inbuf[65536], outbuf[65536];
	size_t in_size = 0, in_pos = 0;
	FILE *f = fopen(argv[1], "rb");
	stream_dec *s = stream_dec_init(UINT64_MAX, DEC_CONCATENATED);
